    // Actual HTTP requests use an isolated loopback server; no remote patch is published.
    public class PatchTestServer:IDisposable
    {
        readonly TcpListener listener=new TcpListener(IPAddress.Loopback,0);volatile bool stopped;
        readonly ConcurrentDictionary<string,byte[]> files=new ConcurrentDictionary<string,byte[]>();public int PayloadDelay,ChunkDelay;
        public string Root {get;private set;}
        public PatchTestServer(){listener.Start();Root="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/patches/";_ = Task.Run(Listen);}
        public void Publish(PatchPackage package,byte[] overrideBody=null){files["manifest.json"]=Encoding.UTF8.GetBytes(JsonUtility.ToJson(package.manifest));files[package.manifest.payloadFile]=overrideBody??Encoding.UTF8.GetBytes(package.payload);}
        async Task Listen(){while(!stopped){TcpClient client;try{client=await listener.AcceptTcpClientAsync();}catch{break;}_ = Task.Run(()=>Serve(client));}}
        async Task Serve(TcpClient client)
        {
            using(client)try{using(var stream=client.GetStream()){var buffer=new byte[8192];int count=await stream.ReadAsync(buffer,0,buffer.Length);string first=Encoding.ASCII.GetString(buffer,0,count).Split('\n')[0];string path=first.Split(' ')[1].Split('?')[0];string name=path.Substring(path.LastIndexOf('/')+1);bool found=files.TryGetValue(name,out var bytes);if(!found)bytes=Encoding.UTF8.GetBytes("Not found");if(name!="manifest.json" && PayloadDelay>0)await Task.Delay(PayloadDelay);byte[] header=Encoding.ASCII.GetBytes("HTTP/1.1 "+(found ? "200 OK" : "404 Not Found")+"\r\nContent-Type: application/json\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n");await stream.WriteAsync(header,0,header.Length);if(name!="manifest.json" && ChunkDelay>0){int half=bytes.Length/2;await stream.WriteAsync(bytes,0,half);await Task.Delay(ChunkDelay);await stream.WriteAsync(bytes,half,bytes.Length-half);}else await stream.WriteAsync(bytes,0,bytes.Length);}}catch{}
        }
        public void Dispose(){stopped=true;listener.Stop();}
    }
