            DontDestroyOnLoad(gameObject);Application.runInBackground=true;Directory.CreateDirectory("Logs");Directory.CreateDirectory("Builds/PatchPreview");root=Path.GetFullPath("Builds/PatchTestData/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
            string saved=PlayerPrefs.GetString(ProgressStore.SaveKey,""),backup=PlayerPrefs.GetString(ProgressStore.BackupKey,"");var artifacts=new[]{"Builds/TreasureRunner.apk","Builds/TreasureRunner-Windows-Werkzeuge.zip","Builds/TreasureRunner-Source-0.7.0.zip"};var digests=artifacts.Select(f=>PatchCodec.Hash(File.ReadAllBytes(f))).ToArray();ProgressStore.BeginMemoryTest();Application.logMessageReceived+=Log;bool failed=false;var sequence=Scenarios();
            while(true){bool more;object current=null;try{more=sequence.MoveNext();if(more)current=sequence.Current;}catch(Exception e){report.Add("FAIL: "+e);failed=true;break;}if(!more)break;yield return current;}
            server?.Dispose();PatchClient.TestRoot=null;PatchRuntime.SetTestStore(null);ProgressStore.EndMemoryTest();Time.timeScale=1;Application.logMessageReceived-=Log;
            if(saved!=PlayerPrefs.GetString(ProgressStore.SaveKey,"") || backup!=PlayerPrefs.GetString(ProgressStore.BackupKey,"")){failed=true;report.Add("FAIL: Real save changed");}else report.Add("PASS: Real player save and backup unchanged");
            if(!digests.SequenceEqual(artifacts.Select(f=>PatchCodec.Hash(File.ReadAllBytes(f))))){failed=true;report.Add("FAIL: Published artifact changed");}else report.Add("PASS: All published APK, Windows and source files unchanged");
            failed|=errors;report.Add(failed ? "DATA PATCH TESTS FAILED" : "ALL DATA PATCH TESTS PASSED");File.WriteAllLines("Logs/DataPatchTests.txt",report);foreach(var line in report)Debug.Log(line);EditorApplication.Exit(failed ? 1 : 0);
        }
