            var blocked=NewStore("diskfailure");blocked.Install(Package(Fixture()),out _);Directory.CreateDirectory(blocked.StatePath+".tmp");Check(!blocked.Install(Package(Fixture(2)),out _) && blocked.Revision==1 && NewStore("diskfailure").Revision==1,"Failed disk write leaves in-memory and on-disk active patch unchanged");var foreign=new PatchStore(Path.Combine(root,"journal"),"8.0.0");foreign.Load();Check(foreign.Revision==0,"Different app version never reuses an old patch");
            var runtime=NewStore("runtime");runtime.Install(Package(Fixture()),out _);PatchRuntime.SetTestStore(runtime);LevelRun.CustomLevel=null;var bow=Array.Find(GameConfig.Current.weapons,w=>w.id=="bow");Check(WeaponUpgrades.Damage(bow)==2 && Mathf.Abs(WeaponUpgrades.Cooldown(bow)-1.05f)<.001f,"Existing weapon service reads active patch values");ProgressStore.Data.weaponUpgrades[2]=2;Check(WeaponUpgrades.Damage(bow)==3 && WeaponUpgrades.Cooldown(bow)<1.05f,"Purchased weapon upgrades still apply to patched base values");ProgressStore.Data.weaponUpgrades[2]=0;
            var baseRoute=WorldRoute.CreateBase(0,0,WorldRoute.SectionCount(0,0));var patched=WorldRoute.Create(0,0,WorldRoute.SectionCount(0,0));Check(Mathf.Abs(patched[1].width-baseRoute[1].width-1)<.001f && Mathf.Abs(patched[2].x-baseRoute[2].x-1)<.001f,"Campaign geometry override rebuilds following section coordinates");
            for(int w=0;w<8;w++)for(int stage=0;stage<10;stage++){var route=WorldRoute.Create(w,stage,WorldRoute.SectionCount(w,stage));Check(route.Select((s,i)=>i==route.Count-1 || JumpProfile.CanCross(s.gap,route[i+1].height-s.height)).All(v=>v),"Patched campaign remains jumpable: "+w+"/"+stage);}
